mapper.select:
SELECT o.*, s.name AS shop_name
FROM orders o LEFT JOIN shop s ON o.shop_id = s.id
WHERE o.id = #{id} AND o.user_id = #{userId}

SELECT o.*, s.name AS shop_name FROM orders o LEFT JOIN shop s ON o.shop_id = s.id WHERE o.user_id = #{userId}
AND o.status = 0 AND o.status = 1 AND o.status = 2 AND o.status = 3 AND o.status IN (4) AND o.status = 5
ORDER BY o.create_time DESC LIMIT #{offset}, #{size}

mapper.update:
UPDATE orders
SET status = #{toStatus}
, pay_time = NOW()
, finish_time = NOW()
WHERE id = #{id} AND status = #{fromStatus} AND user_id = #{userId}

